JoinCompany = {
	companies: [],
    init: function (app, rootBucket) {
        app = app || session.app;
		if (!rootBucket)
			rootBucket = app.Config.B2B.RootBucket;

		JoinCompany.setup(rootBucket);
    },
	setup: function(rootBucket)
	{
		//Company Selector AutoComplete
		//This should be Bucket(rootBucket) then get all Companies in all descendant buckets
		var query = "B2B/Company?$select=Name,Id";
		api.get(query).then(function (data) {
			if(data != null)
			{
				JoinCompany.companies = data.value;
				var ds = data.value.map(function (com){ return com.Name; });
				var companyAutoComplete = $("#companySelector").kendoAutoComplete({
					dataSource: ds,
					select: JoinCompany.onSelect,
					filter: "startswith",
					placeholder: "Select company..."
                });
			}
        });

	},
	onSelect: function()
	{
		$("#userDetailsFormDisplay")[0].style.display = "block";
		$("#submitRequest").off().on('click', JoinCompany.submitRequest);
	},
	submitRequest: function()
	{

		var matchingCompanies = JoinCompany.companies.filter(function(com){ return com.Name == $("#companySelector")[0].value; });
		if(matchingCompanies != null && matchingCompanies.length > 0)
		{
			var body = 
			{
				User: session.user.Id,
				CompanyId: matchingCompanies[0].Id,
				CompanyName: $("#companySelector")[0].value,
				DateCreated: kendo.toString(new Date(), 'dd/MM/yyyy'),
				FullName:  $("#fullName")[0].value,
				JobTitle:  $("#jobTitle")[0].value,
				PhoneNumber:  $("#phoneNumber")[0].value,
				EmailAddress: session.user.Email
			};

			// Create DMS file
			api.add("DMS/Data/JoinCompanyRequests/" + body.User + "_" + body.CompanyId + ".json", body, function(result) {
				notification.success("[resource_displayname[JoinCompanyRequestSuccessfullyPosted]]");
			});
		}
	}
}
